esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to deposit; this contract must hold at least `amount` when called
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record balances before any interaction
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        // make a deposit to c (uses nonReentrant_ in C)
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        // record after deposit
        uint256 afterDepositContractBal = address(c).balance;
        uint256 afterDepositUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        // attempt withdraw and capture whether it reverted
        bool withdrewReverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        // record after withdraw attempt
        uint256 afterWithdrawContractBal = address(c).balance;
        uint256 afterWithdrawUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        // General invariant to assert:
        // If withdraw did not revert, then (1) the on-chain recorded user balance is zero
        // and (2) the contract's balance did not increase compared to afterDepositContractBal
        // (i.e., it decreased or stayed same by at least the withdrawn amount). If withdraw reverted,
        // then the recorded user balance must remain unchanged from afterDepositUserBal.
        assert(
            (!withdrewReverted && afterWithdrawUserBal == 0 && afterWithdrawContractBal <= afterDepositContractBal)
            || (withdrewReverted && afterWithdrawUserBal == afterDepositUserBal)
        );
    }

    // allow receiving Ether when c calls back
    receive() external payable { }
 }

