// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUserBal = __r; } catch { return; }
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 afterDepositContractBal = address(c).balance;
        uint256 afterDepositUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterDepositUserBal = __r; } catch { return; }
        bool withdrewReverted;
        try c.withdrawBalance() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint256 afterWithdrawContractBal = address(c).balance;
        uint256 afterWithdrawUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterWithdrawUserBal = __r; } catch { return; }
        assertTrue((!withdrewReverted && afterWithdrawUserBal == 0 && afterWithdrawContractBal <= afterDepositContractBal)
            || (withdrewReverted && afterWithdrawUserBal == afterDepositUserBal));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
